// Bổ sung lý thuyết / lỗi hay gặp / keycards / why cho 6 lab tuần 1 (vá thẳng vào DATA.labs, không sửa labs.js)
(function () {
  var EXTRA = {

    /* ============================== SETUP-1 ============================== */
    "SETUP-1": {
      theory: [
        { title: "Ảo hóa (virtualization) là gì?", body: "Một máy thật (<b>host</b>) chạy nhiều máy ảo (<b>guest / VM</b>), mỗi VM tưởng mình có CPU, RAM, ổ đĩa, card mạng riêng. Phần mềm chia tài nguyên gọi là <b>hypervisor</b>. CPU cần tính năng phần cứng <b>Intel VT-x</b> hoặc <b>AMD-V (SVM)</b> thì VM mới chạy nhanh – vì vậy phải bật trong BIOS.<br>Ví dụ đời thường: host = tòa nhà, VM = từng căn hộ, hypervisor = ban quản lý chia điện nước." },
        { title: "Hypervisor type 1 và type 2", body: "<b>Type 1 (bare-metal)</b>: cài thẳng lên phần cứng, không cần hệ điều hành bên dưới – VMware <b>ESXi</b>, <b>Microsoft Hyper-V</b>, <b>Proxmox/KVM</b>. Dùng trong datacenter.<br><b>Type 2 (hosted)</b>: là một ứng dụng chạy trên Windows/Linux/macOS – <b>VMware Workstation</b>, <b>VirtualBox</b>. Dùng cho lab, máy cá nhân.<br>Khi bật Hyper-V/VBS, Windows thực ra chạy <b>trên</b> Hyper-V, nên VMware phải “đi nhờ” qua Windows Hypervisor Platform → có thể chậm hơn." },
        { title: "3 kiểu mạng ảo: NAT, Host-only, Bridged", body: "<b>NAT (VMnet8)</b>: VM ra Internet <b>mượn IP của host</b>; bên ngoài không chủ động vào được VM. Giống nhà trong hẻm đi ra đường lớn qua một cổng chung.<br><b>Host-only (VMnet1, và VMnet2/3/4 ta tự tạo)</b>: switch ảo kín, không có đường ra ngoài; nếu bỏ tick host adapter thì <b>cả host cũng không vào được</b> → mạng cô lập hoàn toàn.<br><b>Bridged (VMnet0)</b>: VM cắm thẳng vào mạng nhà như một máy thật, nhận IP từ router nhà – <b>không dùng</b> cho lab tấn công vì máy Kali sẽ nằm chung mạng với điện thoại, TV của gia đình." },
        { title: "Phân đoạn mạng (network segmentation) & IP plan", body: "Chia mạng thành nhiều vùng nhỏ (Server / Client / Attacker); đi giữa các vùng <b>bắt buộc qua firewall</b>. Lợi ích: một máy bị nhiễm khó lây sang vùng khác (giảm <b>lateral movement</b>), dễ viết luật và dễ đọc log. (Khóa 3 – network segmentation, security zones.)<br><b>IP plan</b> là bảng ghi trước subnet, gateway, dải DHCP, IP tĩnh – admin viết bảng này <b>trước</b> khi cấu hình để không trùng IP." },
        { title: "Subnet /24 và dải IP riêng (RFC 1918)", body: "<code>10.10.10.0/24</code> = mask <code>255.255.255.0</code> → 256 địa chỉ, dùng được <b>.1 – .254</b> (.0 là địa chỉ mạng, .255 là broadcast).<br>3 dải IP riêng (không đi trên Internet): <code>10.0.0.0/8</code>, <code>172.16.0.0/12</code>, <code>192.168.0.0/16</code>. Lab chọn 10.10.x.x để <b>không trùng</b> mạng nhà 192.168.x.x – nếu trùng, máy không biết gói nên đi đường nào (lỗi định tuyến)." },
        { title: "DHCP chỉ nên có MỘT server trên một phân đoạn", body: "DHCP là dịch vụ tự cấp IP, gateway, DNS cho máy. Nếu một mạng có 2 DHCP server (VMware + pfSense), máy nhận IP từ ai trả lời nhanh hơn → có lúc nhận gateway sai, lỗi lúc có lúc không, rất khó debug. Vì vậy tắt DHCP của VMware trên VMnet2/3/4, để pfSense cấp." },
        { title: "Snapshot ≠ Backup", body: "<b>Snapshot</b> = “điểm lưu game”: ghi lại trạng thái VM tại một thời điểm, các thay đổi sau đó ghi vào file đĩa phụ (delta). Quay lại rất nhanh, nhưng <b>nằm cùng chỗ</b> với VM – ổ hỏng là mất cả hai.<br><b>Backup</b> = bản sao độc lập để <b>ở nơi khác</b> (ổ khác, cloud). Snapshot để thử nghiệm an toàn; backup để phục hồi khi mất dữ liệu. Snapshot để quá lâu, quá nhiều còn làm VM chậm và tốn dung lượng." }
      ],
      pitfalls: [
        "<b>Virtualization vẫn Disabled</b> sau khi vào BIOS: quên bấm <b>Save & Exit</b>, hoặc bật nhầm mục (VT-d là ảo hóa I/O, cái cần là <b>VT-x</b> / <b>SVM Mode</b>).",
        "<b>Để thư mục VM trong Google Drive</b> (<code>G:\\My Drive</code>): Drive đồng bộ file .vmdk hàng chục GB → nghẽn mạng, file khóa, VM hỏng. Luôn dùng ổ riêng như <code>D:\\VMs</code>.",
        "<b>Quên bỏ tick DHCP</b> trên VMnet2/3/4 → sau này có 2 DHCP server (VMware + pfSense), máy nhận sai gateway. Kiểm tra cột DHCP trong Virtual Network Editor phải trống.",
        "<b>Để tick “Connect a host virtual adapter”</b>: VMware tự gán cho host IP <b>.1</b> (vd 10.10.10.1) – trùng đúng IP pfSense sẽ dùng làm gateway → xung đột IP.",
        "<b>Không bấm Change Settings</b> (cần quyền admin) nên các ô trong Virtual Network Editor bị mờ, không sửa được; hoặc sửa xong quên <b>Apply</b>.",
        "<b>Chọn subnet lab trùng mạng nhà</b> (vd cũng 192.168.1.0/24) → host không biết gói đi ra router nhà hay vào lab, mất Internet hoặc mất lab."
      ],
      keycards: [
        { front: "Hypervisor type 1 khác type 2 thế nào? Cho ví dụ.", def: "<b>Type 1 (bare-metal)</b> chạy thẳng trên phần cứng: VMware ESXi, Hyper-V, Proxmox/KVM – dùng trong datacenter.<br><b>Type 2 (hosted)</b> là ứng dụng chạy trên một OS có sẵn: VMware Workstation, VirtualBox – dùng cho lab cá nhân.", example: "Type 1 = căn hộ xây thẳng trên móng; type 2 = phòng trọ ngăn ra bên trong một căn nhà đã có người ở.", trap: "Hyper-V là type 1 dù bạn bật nó từ “Windows Features” – khi bật, chính Windows chạy trên Hyper-V.", interview: "Công ty bạn chạy server trên VMware ESXi – đó là loại hypervisor nào, khác gì Workstation trên laptop?" },
        { front: "So sánh mạng ảo NAT, Host-only và Bridged.", def: "<b>NAT</b>: VM ra Internet qua IP của host, bên ngoài không chủ động vào được VM.<br><b>Host-only</b>: mạng kín giữa các VM (và host nếu có host adapter), không ra Internet.<br><b>Bridged</b>: VM cắm thẳng vào mạng thật, nhận IP từ router nhà như một máy riêng.", example: "NAT = đi ra đường qua cổng chung của khu trọ; host-only = phòng kín chỉ có người trong phòng nói chuyện; bridged = có cửa riêng mở ra mặt đường.", trap: "Không dùng Bridged cho máy tấn công (Kali) – nó sẽ nằm chung mạng với thiết bị thật của gia đình/công ty.", interview: "Bạn dựng lab malware analysis – chọn kiểu mạng nào cho VM phân tích? Vì sao?" },
        { front: "Vì sao phải tắt DHCP của VMware trên các mạng host-only của lab?", def: "Vì pfSense sẽ làm DHCP server cho các phân đoạn đó. Hai DHCP server trên cùng một mạng → máy nhận IP/gateway từ ai trả lời trước → lúc đúng lúc sai (gateway của VMware không đi qua pfSense).", example: "Một lớp học có 2 cô giáo cùng phát số báo danh – học sinh nhận số trùng hoặc sai phòng thi.", trap: "Lỗi này không báo đỏ ở đâu cả; triệu chứng là “lúc được lúc không” – luôn kiểm tra <code>ip route</code> xem default gateway có đúng pfSense không.", interview: "Một máy nhận IP đúng dải nhưng gateway lạ – bạn nghi gì? (rogue DHCP server)" },
        { front: "Dải IP riêng RFC 1918 gồm những dải nào? /24 có bao nhiêu host dùng được?", def: "<code>10.0.0.0/8</code>, <code>172.16.0.0/12</code>, <code>192.168.0.0/16</code>.<br>/24 (255.255.255.0) có 256 địa chỉ, <b>254 host dùng được</b> (.1–.254); .0 là địa chỉ mạng, .255 là broadcast.", example: "Lab: 10.10.10.0/24 → pfSense .1, ubuntu-srv .10, DHCP .100–.199, host tạm .250.", trap: "172.16.0.0/12 chỉ đến 172.31.255.255 – 172.32.x.x là IP công khai, không phải IP riêng.", interview: "Vì sao không nên đặt subnet lab trùng subnet mạng nhà?" },
        { front: "Snapshot khác Backup thế nào?", def: "<b>Snapshot</b> lưu trạng thái VM tại một thời điểm, nằm cùng nơi với VM, quay lại rất nhanh – dùng trước khi thử nghiệm.<br><b>Backup</b> là bản sao độc lập lưu ở nơi khác – dùng khi ổ đĩa hỏng, mất dữ liệu, ransomware.", example: "Snapshot = điểm lưu game; backup = chép file save sang USB cất ở nhà khác.", trap: "Xóa/hỏng thư mục VM là mất luôn mọi snapshot. Snapshot giữ quá lâu còn làm VM chậm.", interview: "Trước khi sửa firewall rule production, bạn chuẩn bị đường lui thế nào? (backup config + có kế hoạch rollback)" },
        { front: "VT-x / AMD-V là gì? Kiểm tra ở đâu trên Windows?", def: "Tính năng ảo hóa phần cứng của CPU (Intel VT-x, AMD-V/SVM) giúp hypervisor chạy VM nhanh và an toàn. Kiểm tra: <b>Task Manager → Performance → CPU → Virtualization: Enabled</b>; nếu Disabled thì bật trong BIOS/UEFI.", trap: "VT-d (Intel) là ảo hóa thiết bị I/O, không phải VT-x. Bật VT-d mà không bật VT-x thì VM vẫn không chạy.", interview: "VM báo lỗi “This host supports Intel VT-x, but VT-x is disabled” – bạn xử lý thế nào?" },
        { front: "Network segmentation giúp gì cho bảo mật?", def: "Chia mạng thành nhiều vùng (Server, Client, Guest, DMZ…), đi giữa các vùng phải qua firewall → giới hạn <b>lateral movement</b> khi một máy bị chiếm, áp dụng least privilege theo vùng, và log ở firewall cho thấy ai đi đâu.", example: "Tòa nhà chia tầng, mỗi tầng có cửa quẹt thẻ – trộm vào được sảnh chưa chắc lên được phòng két.", trap: "Chia subnet mà không đặt luật firewall giữa chúng (cho any-any) thì gần như không có tác dụng bảo mật.", interview: "Một máy trong mạng Client nhiễm ransomware – segmentation giúp hạn chế thiệt hại ra sao?" }
      ],
      whys: [
        "Hypervisor cần CPU hỗ trợ ảo hóa phần cứng (<b>VT-x / AMD-V</b>). Không bật thì VMware báo lỗi hoặc VM 64-bit không chạy – kiểm tra trước để không mất thời gian debug về sau.",
        "Khi Hyper-V/VBS bật, Windows giữ quyền hypervisor (type 1) và VMware phải chạy qua lớp Windows Hypervisor Platform. Biết trạng thái này giúp giải thích khi VM chậm, và là một <b>quyết định bảo mật có ý thức</b> chứ không làm theo phản xạ.",
        "VM là các file đĩa rất lớn, đọc ghi liên tục. Đặt trên SSD riêng thì nhanh; đặt trong Google Drive thì bị đồng bộ liên tục → hỏng file. Tính trước dung lượng = <b>capacity planning</b>, kỹ năng cơ bản của admin.",
        "Chỉ tải phần mềm từ <b>nguồn chính thức</b> – bản crack hay web lạ là đường lây malware phổ biến (supply chain). Đây cũng là thói quen SOC hay khuyên người dùng.",
        "Cài hypervisor type 2 lên Windows. Đặt <b>Default VM location</b> ngay từ đầu để mọi VM sau này tự nằm đúng ổ, không lỡ rơi vào Google Drive.",
        "Biết phương án thay thế giúp không bị kẹt. Quan trọng là hiểu <b>logic mạng</b> (1 NAT + 3 mạng cô lập, không DHCP của hypervisor) – tên menu chỉ là chi tiết.",
        "Viết <b>IP plan</b> trước khi cấu hình là thói quen của admin: tránh trùng IP, tránh trùng subnet với mạng nhà, và bảng này chính là tài liệu mạng đầu tiên trong portfolio.",
        "Tạo 3 switch ảo <b>host-only</b> = 3 phân đoạn cô lập. Bỏ host adapter để host không cắm vào (cô lập thật, tránh host lấy IP .1); bỏ DHCP để pfSense là DHCP server duy nhất.",
        "VMnet8 là “cổng ra Internet” duy nhất của lab: chỉ pfSense WAN dùng nó. Ghi lại subnet và gateway (.2) để sau này đọc <code>Status → Interfaces</code> trên pfSense là hiểu ngay.",
        "Snapshot cho phép <b>thử – sai – quay lại</b> trong vài giây, nên dám làm lab mạnh tay. Đặt tên có thứ tự để biết mỗi điểm lưu ứng với bài nào. Nhưng snapshot không thay được backup."
      ]
    },

    /* ============================== SETUP-2 ============================== */
    "SETUP-2": {
      theory: [
        { title: "ISO và kiểm tra hash", body: "File <b>ISO</b> là ảnh của đĩa cài đặt. Trang tải thường kèm file <b>SHA256SUMS</b>: tính hash của file bạn tải (<code>Get-FileHash</code>) và so với giá trị công bố – khớp thì file <b>nguyên vẹn, không bị sửa</b> (integrity, chữ I trong CIA triad – Khóa 1/2). Hash khác dù chỉ 1 ký tự = file lỗi hoặc bị giả mạo." },
        { title: "Phần cứng ảo của VM", body: "vCPU, RAM, ổ đĩa, card mạng của VM đều là “ảo” và có thể đổi sau khi tắt máy. Server không giao diện đồ họa rất nhẹ: 1 vCPU, 2 GB RAM, 20 GB là đủ. Ổ đĩa ảo mặc định <b>thin provisioned</b> – dùng tới đâu chiếm chỗ thật tới đó." },
        { title: "LVM (Logical Volume Manager)", body: "LVM xếp ổ đĩa thành 3 lớp: <b>PV</b> (physical volume – ổ/phân vùng thật) → <b>VG</b> (volume group – “bể” dung lượng chung) → <b>LV</b> (logical volume – phần cắt ra để dùng, vd <code>ubuntu-lv</code> gắn vào <code>/</code>). Lợi ích: mở rộng dung lượng khi máy đang chạy. <code>lvextend -r</code> nới LV và <b>resize luôn filesystem</b>." },
        { title: "IP, gateway, DNS – 3 thứ máy cần để ra Internet", body: "<b>IP + subnet mask</b>: địa chỉ và biết ai cùng mạng. <b>Default gateway</b>: “cửa ra” cho mọi gói đi tới mạng khác (<code>ip route</code> → <code>default via …</code>). <b>DNS server</b>: đổi tên miền thành IP.<br>Cách khoanh vùng lỗi (Khóa 3): ping gateway → ping 1.1.1.1 (lớp IP) → ping tên miền (DNS). Ping IP được mà tên miền không được = <b>lỗi DNS</b>." },
        { title: "systemd-resolved & netplan trên Ubuntu", body: "<b>netplan</b> là file YAML trong <code>/etc/netplan/</code> mô tả cấu hình mạng; <code>netplan apply</code> chuyển nó cho <b>systemd-networkd</b> thực thi. DNS do <b>systemd-resolved</b> lo: <code>/etc/resolv.conf</code> trỏ tới <code>127.0.0.53</code> (bộ đệm nội bộ), xem DNS thật bằng <code>resolvectl status</code>." },
        { title: "SSH, port 22 & socket activation", body: "<b>SSH</b> = quản trị từ xa có mã hóa, mặc định <b>TCP 22</b> (thay cho Telnet 23 gửi rõ chữ). Ubuntu 24.04 dùng <b>socket activation</b>: <code>ssh.socket</code> (systemd) giữ port 22, chỉ bật <code>ssh.service</code> khi có kết nối → service <i>inactive</i> lúc rảnh là bình thường. Kiểm tra port đang nghe bằng <code>ss -tlnp</code> (t=TCP, l=listening, n=số, p=process)." },
        { title: "Host key fingerprint & MITM", body: "Lần đầu SSH, client hiện <b>fingerprint</b> của server và lưu vào <code>known_hosts</code> (TOFU – Trust On First Use). Lần sau nếu fingerprint đổi, SSH cảnh báo – có thể server cài lại, hoặc có kẻ đứng giữa (<b>on-path / MITM</b>)." }
      ],
      pitfalls: [
        "<b>Chọn Easy Install</b> (trỏ ISO ngay trong wizard) → VMware tự cài theo cách của nó, bỏ qua các lựa chọn quan trọng. Chọn <b>I will install the operating system later</b>.",
        "<b>Quên tick Install OpenSSH server</b> lúc cài → không SSH vào được. Sửa: <code>sudo apt install -y openssh-server</code>.",
        "<b>Ổ / chỉ có ~10 GB</b> dù disk 20 GB: trình cài chỉ cấp một nửa cho <code>ubuntu-lv</code>. Kiểm tra <code>df -h /</code>, mở rộng bằng <code>lvextend -r -l +100%FREE</code>.",
        "<b>Thấy <code>ssh.service</code> inactive và tưởng SSH hỏng</b> – trên 24.04 phải xem <code>ssh.socket</code> và <code>ss -tlnp | grep :22</code>.",
        "<b>Ping tên miền thất bại và kết luận “mất mạng”</b>: phải ping IP (1.1.1.1) trước. IP được, tên miền không được = lỗi DNS.",
        "<b>Gắn VMnet2 quá sớm</b> (trước khi xong N1) rồi để DHCP → máy không có IP, <code>apt update</code> lỗi. Dùng NAT lúc cài, chuyển sang VMnet2 ở cuối N1."
      ],
      keycards: [
        { front: "Lệnh Linux nào xem IP, default gateway và DNS đang dùng?", def: "<code>ip a</code> (hoặc <code>ip -br a</code>) → IP từng card.<br><code>ip route</code> → dòng <code>default via X</code> là gateway.<br><code>resolvectl status</code> → DNS server thật (vì <code>/etc/resolv.conf</code> chỉ trỏ tới 127.0.0.53).", example: "Ubuntu trong lab: <code>default via 10.10.10.1</code>, DNS 10.10.10.1 = pfSense.", trap: "<code>ifconfig</code> là lệnh cũ (gói net-tools), Ubuntu Server mới không cài sẵn – dùng <code>ip</code>.", interview: "Một server Linux không ra Internet – 3 lệnh đầu tiên bạn chạy là gì?" },
        { front: "Ping 1.1.1.1 được nhưng ping ubuntu.com không được – lỗi ở đâu?", def: "Lớp IP và đường ra Internet vẫn tốt; lỗi nằm ở <b>DNS</b> (không phân giải được tên). Kiểm tra DNS server đang dùng (<code>resolvectl status</code>), thử <code>dig @&lt;dns&gt; ubuntu.com</code>, kiểm tra firewall có chặn port 53 không.", example: "Biết số điện thoại thì gọi được, nhưng danh bạ hỏng nên gọi theo tên không được.", trap: "Đừng khởi động lại cả máy/router ngay – khoanh vùng theo lớp trước.", interview: "Người dùng báo “không vào được web”. Bạn khoanh vùng lỗi từng bước thế nào?" },
        { front: "Trên Ubuntu 24.04, vì sao <code>ssh.service</code> inactive mà vẫn SSH vào được?", def: "Do <b>socket activation</b>: <code>ssh.socket</code> của systemd luôn nghe TCP 22 và chỉ khởi động <code>ssh.service</code> khi có kết nối tới. Kiểm tra bằng <code>systemctl status ssh.socket</code> và <code>sudo ss -tlnp | grep :22</code>.", trap: "Trên Ubuntu 22.04 trở về trước, sshd chạy thường trực – <code>ssh.service</code> active.", interview: "Làm sao biết một port đang mở và tiến trình nào giữ nó trên Linux?" },
        { front: "<code>ss -tlnp</code> – từng chữ cái nghĩa là gì?", def: "<b>t</b> = TCP, <b>l</b> = chỉ socket đang LISTEN, <b>n</b> = hiện số (không đổi port thành tên), <b>p</b> = hiện process giữ socket (cần sudo). Thay <code>t</code> bằng <code>u</code> để xem UDP.", example: "<code>sudo ss -tlnp | grep ':22'</code> → thấy <code>LISTEN 0.0.0.0:22 … systemd</code>.", trap: "Không có sudo thì cột process có thể trống – không phải port không mở.", interview: "SOC phát hiện server nghe một port lạ 4444 – bạn tìm process nào mở nó bằng cách nào?" },
        { front: "LVM gồm những lớp nào? <code>lvextend -r</code> làm gì?", def: "<b>PV</b> (ổ/phân vùng thật) → <b>VG</b> (bể dung lượng gộp) → <b>LV</b> (phần cắt ra dùng, gắn vào thư mục như <code>/</code>).<br><code>lvextend -r -l +100%FREE</code> nới LV lấy hết chỗ trống trong VG và <b>-r</b> resize luôn filesystem.", example: "VG = cái bánh; LV = miếng bánh đã cắt; còn thừa bánh thì cắt miếng to hơn.", trap: "Quên <code>-r</code> thì LV to ra nhưng <code>df -h</code> vẫn thấy cũ vì filesystem chưa được nới.", interview: "Server báo đầy ổ / nhưng VG còn trống – bạn xử lý thế nào?" },
        { front: "SHA256 hash của file ISO dùng để làm gì?", def: "Kiểm tra <b>integrity</b>: hash tính trên file tải về phải khớp với hash nhà phát hành công bố. Khác dù 1 ký tự = file lỗi hoặc bị sửa (có thể bị cài malware).", example: "Như so số seri niêm phong trên hộp sữa với số trên web hãng.", trap: "Hash chỉ chứng minh file giống bản gốc; nếu kẻ xấu sửa cả trang web chứa hash thì vô nghĩa – vì vậy có thêm chữ ký GPG.", interview: "Hash khác mã hóa thế nào? (hash là một chiều, không giải ngược được)" },
        { front: "Lần đầu SSH vào server, câu hỏi “Are you sure you want to continue connecting (yes/no)?” có ý nghĩa gì?", def: "Client chưa từng thấy server này, hiện <b>fingerprint</b> host key để bạn xác nhận; trả lời yes thì lưu vào <code>~/.ssh/known_hosts</code> (TOFU). Lần sau nếu key đổi, SSH cảnh báo – dấu hiệu có thể là <b>MITM</b>.", trap: "Cảnh báo “REMOTE HOST IDENTIFICATION HAS CHANGED” không được bỏ qua bằng cách xóa dòng cũ khi chưa xác minh.", interview: "TOFU có điểm yếu gì?" }
      ],
      whys: [
        "Thứ tự phụ thuộc: VMnet2 chưa có gateway/DHCP khi pfSense chưa dựng. Dùng NAT tạm thời để có Internet cập nhật trước – hiểu <b>thứ tự phụ thuộc</b> là kỹ năng lập kế hoạch của admin.",
        "Ubuntu <b>LTS</b> được hỗ trợ bản vá 5 năm – server luôn chọn bản LTS. Tải từ trang chính thức và so <b>SHA256</b> để chắc file toàn vẹn (integrity).",
        "Chọn “install later” để tự kiểm soát quá trình cài. Cấu hình phần cứng ảo vừa đủ (1 vCPU, 2 GB) để nhiều VM chạy cùng lúc trên một host.",
        "Mỗi lựa chọn có lý do: Ubuntu Server (không GUI) = <b>attack surface</b> nhỏ; LVM để mở rộng sau; <b>OpenSSH</b> để quản trị từ xa; không cài snap thừa = least functionality.",
        "Kiểm tra theo lớp: IP → route (gateway) → DNS → ping IP → ping tên. Đây là quy trình khoanh vùng lỗi mạng chuẩn, và cặp “ping IP được / tên miền không” chính là ý tưởng của bài S8.",
        "Vá ngay sau khi cài (<b>patch management</b>). Cài sẵn công cụ phân tích mạng (tcpdump, dig, nc, curl) cho N2/S8; <code>open-vm-tools</code> giúp VMware quản lý VM tốt hơn. Mở rộng LVM để không đầy ổ giữa chừng.",
        "Xác nhận dịch vụ quản trị từ xa thật sự đang nghe port 22 (<code>ss</code>) và đăng nhập thử từ host. Hiểu <b>socket activation</b> để không chẩn đoán sai “SSH chết”.",
        "Ghi MAC và tên card để sau này đối chiếu trong <b>DHCP Leases</b> của pfSense (MAC → IP → hostname) – đây cũng là cách SOC xác định “máy nào” trong log. Snapshot sạch = điểm quay lại an toàn.",
        "Chuyển VM vào đúng phân đoạn SERVER để từ nay mọi lưu lượng của nó đi qua pfSense – nơi có firewall và log. Đây là bước đặt máy vào đúng <b>security zone</b>."
      ]
    },

    /* ============================== N1 ============================== */
    "N1": {
      theory: [
        { title: "Router và Firewall", body: "<b>Router</b> (lớp 3) nối nhiều mạng khác nhau và chuyển gói giữa chúng dựa trên IP đích. <b>Firewall</b> quyết định gói nào được đi, gói nào bị chặn theo luật. pfSense làm <b>cả hai</b>: mỗi card mạng là cổng vào một mạng, mọi gói đi giữa các mạng đều phải qua bộ lọc của nó." },
        { title: "Broadcast domain, VLAN và “VLAN logic” trong lab", body: "Mỗi switch (hoặc VLAN) là một <b>broadcast domain</b>: gói broadcast (ARP, DHCP Discover) chỉ lan trong đó. Muốn đi sang domain khác phải qua <b>router</b>.<br><b>802.1Q VLAN</b> chia <i>một</i> switch vật lý thành nhiều mạng logic bằng cách gắn <b>tag VLAN ID</b> vào frame; cổng <b>access</b> thuộc 1 VLAN, cổng <b>trunk</b> mang nhiều VLAN có tag.<br>Lab này dùng <b>nhiều switch ảo riêng</b> (VMnet2/3/4) + nhiều card trên pfSense: kết quả logic giống 3 VLAN nhưng <b>không có tag, không có trunk</b>." },
        { title: "WAN, LAN, OPT trên pfSense", body: "<b>WAN</b>: cổng ra ngoài (có gateway, mặc định chặn mọi kết nối mới đi vào). <b>LAN</b>: mạng nội bộ đầu tiên, có sẵn rule <i>Default allow LAN to any</i> và <i>Anti-Lockout</i>. <b>OPT1, OPT2…</b>: các mạng thêm, <b>không có rule nào</b> lúc mới tạo → mọi thứ bị chặn (implicit deny)." },
        { title: "DHCP – quy trình DORA", body: "Máy mới cắm mạng chưa có IP nên gửi broadcast:<br><b>D</b>iscover (client → broadcast: “có DHCP server nào không?”) → <b>O</b>ffer (server đề nghị IP) → <b>R</b>equest (client xin đúng IP đó) → <b>A</b>ck (server xác nhận, kèm mask, gateway, DNS, thời gian thuê – lease).<br>Dùng <b>UDP 67</b> (server) và <b>UDP 68</b> (client). Không nhận được DHCP → Windows/Linux có thể tự đặt <b>169.254.x.x</b> (APIPA/link-local) = dấu hiệu không liên lạc được DHCP server." },
        { title: "Default gateway", body: "Khi gửi tới IP <b>khác subnet</b>, máy gửi gói cho gateway để gateway chuyển tiếp. Gateway phải <b>cùng subnet</b> với máy. Trong lab, mỗi phân đoạn có gateway là IP pfSense trên phân đoạn đó (.1). Interface nội bộ của pfSense <b>không</b> có upstream gateway – chỉ WAN có." },
        { title: "Outbound NAT (Source NAT / PAT)", body: "IP riêng 10.10.x.x không đi được trên Internet. Khi gói ra WAN, pfSense <b>đổi IP nguồn</b> thành IP WAN của nó và ghi nhớ trong bảng state để trả gói về đúng máy (nhiều máy dùng chung 1 IP, phân biệt bằng port = <b>PAT</b>).<br>Lab có nhiều lớp NAT: pfSense → VMware NAT (VMnet8) → thường thêm router nhà → Internet." },
        { title: "IP tĩnh cho server, DHCP cho client", body: "Server cần <b>địa chỉ cố định</b> để client, DNS, firewall rule và log luôn trỏ đúng. Có 2 cách: đặt tĩnh trên máy (netplan) <b>hoặc</b> DHCP Static Mapping (reservation) theo MAC. IP tĩnh nên nằm <b>ngoài dải DHCP pool</b> để không bị cấp trùng." }
      ],
      pitfalls: [
        "<b>Gán nhầm WAN/LAN</b> (em0/em1) vì không đối chiếu MAC → pfSense cấp DHCP ra mạng NAT, LAN không có IP. Luôn so MAC trong VM Settings → Advanced với MAC pfSense hiện ở menu Assign.",
        "<b>Host adapter VMnet2 lấy IP 10.10.10.1</b> (VMware tự gán .1) → trùng IP pfSense LAN, GUI lúc vào được lúc không. Đặt host adapter thành <code>10.10.10.250</code>, không gateway, không DNS.",
        "<b>DHCP của VMware vẫn bật</b> trên VMnet2/3/4 → máy nhận gateway sai (của VMware, không qua pfSense).",
        "<b>Test-vm ở OPT1 không ping được gì và tưởng hỏng</b>: OPT mới chưa có rule → implicit deny. DHCP vẫn chạy vì pfSense tự cho phép DHCP khi bật DHCP server.",
        "<b>Clone VM giữ nguyên IP tĩnh .10 và machine-id</b> → trùng IP với ubuntu-srv, hoặc DHCP cấp cùng một IP cho 2 máy. Đổi netplan về DHCP và tạo lại machine-id.",
        "<b>YAML netplan dùng Tab</b> hoặc thụt lề lệch → <code>netplan</code> báo lỗi. Dùng dấu cách và <code>netplan try</code> để tự quay lại sau 120 giây nếu mất kết nối."
      ],
      keycards: [
        { front: "Phân đoạn mạng bằng nhiều VMnet (nhiều card trên pfSense) khác 802.1Q VLAN thế nào?", def: "Cả hai đều tạo nhiều <b>broadcast domain</b> tách biệt, đi giữa chúng phải qua router/firewall.<br><b>802.1Q</b> chia <i>một</i> switch/một dây bằng cách gắn <b>VLAN tag</b> vào frame; cần cổng <b>trunk</b> để mang nhiều VLAN trên 1 dây. Lab VMnet: mỗi mạng là một switch ảo riêng + card riêng → <b>không tag, không trunk</b>.", example: "VLAN = một tòa nhà chia phòng bằng vách; lab VMnet = mỗi phòng là một tòa nhà riêng, có đường đi riêng tới nhà bảo vệ.", trap: "Đừng nói trong phỏng vấn là lab “đã cấu hình VLAN 802.1Q” – nói “VLAN logic / network segment, mỗi segment một interface”.", interview: "Khi nào cần trunk? (khi một dây phải mang nhiều VLAN: switch–switch, switch–router on-a-stick)" },
        { front: "DHCP hoạt động thế nào (DORA)? Dùng port nào?", def: "<b>Discover</b> (client broadcast) → <b>Offer</b> (server đề nghị IP) → <b>Request</b> (client xin IP đó) → <b>Ack</b> (server xác nhận + mask, gateway, DNS, lease time).<br>UDP <b>67</b> = server, UDP <b>68</b> = client.", example: "Vào khách sạn: hỏi lễ tân còn phòng không → lễ tân đưa số phòng → bạn xác nhận lấy phòng đó → lễ tân giao chìa và giờ trả phòng.", trap: "DHCP Discover là broadcast nên không tự qua router – muốn cấp DHCP cho subnet khác cần <b>DHCP relay</b> (<code>ip helper-address</code> trên Cisco) hoặc router chính là DHCP server như pfSense.", interview: "Máy nhận IP 169.254.x.x – nghĩa là gì, bạn kiểm tra gì?" },
        { front: "Máy nhận IP 169.254.x.x nghĩa là gì?", def: "Đó là địa chỉ <b>link-local / APIPA</b>, máy tự đặt khi <b>không nhận được trả lời từ DHCP server</b>. Kiểm tra: dây/card mạng có đúng mạng không (đúng VMnet), DHCP server có bật trên interface đó không, dải pool còn trống không, firewall có chặn không.", example: "Gọi lễ tân mãi không ai nghe, bạn tự lấy tạm một cái ghế ngồi ngoài sảnh – không vào được phòng nào.", trap: "169.254 không phải do DHCP cấp sai; nó chứng tỏ DHCP <b>không trả lời</b>.", interview: "Một phòng ban cả chục máy cùng nhận 169.254 – nghi ngờ đầu tiên là gì?" },
        { front: "Outbound NAT trên pfSense làm gì với gói từ 10.10.10.10 đi 1.1.1.1?", def: "Khi gói ra WAN, pfSense đổi <b>IP nguồn</b> 10.10.10.10 thành <b>IP WAN</b> của nó (và có thể đổi port nguồn), ghi vào <b>state table</b>; gói trả lời về được đổi ngược lại và gửi đúng cho 10.10.10.10. Đây là Source NAT / PAT.", example: "Cả công ty gửi thư bằng một địa chỉ công ty; lễ tân nhìn mã số trên phong bì để chuyển thư trả lời đúng người.", trap: "Trong lab có ít nhất 2 lớp NAT (pfSense và VMware NAT), thường thêm router nhà → IP nguồn mà Internet thấy là IP công khai của nhà bạn.", interview: "NAT có phải là một biện pháp bảo mật không? (giấu IP nội bộ nhưng không thay được firewall)" },
        { front: "Vì sao trên pfSense, LAN ra Internet được ngay còn OPT1/OPT2 mới tạo thì không?", def: "LAN có sẵn rule <b>Default allow LAN to any</b> (IPv4 + IPv6). Interface OPT mới tạo <b>không có rule nào</b> → mọi kết nối bị chặn theo <b>implicit deny</b>. Phải tự viết rule cho OPT.", trap: "DHCP trên OPT vẫn chạy (nhận được IP) vì pfSense tự thêm rule ẩn cho DHCP khi bật DHCP server – nhận IP được không có nghĩa là đi được.", interview: "Implicit deny là gì? Vì sao đó là mặc định tốt?" },
        { front: "Default gateway là gì? Khi nào máy cần đến nó?", def: "Là IP của router trên <b>cùng subnet</b>, nơi máy gửi mọi gói có đích <b>ngoài subnet</b> của mình. Gửi tới máy cùng subnet thì không cần gateway (dùng ARP tìm MAC trực tiếp).", example: "Muốn gửi thư ra tỉnh khác thì đưa cho bưu cục đầu ngõ; gửi cho hàng xóm thì tự mang qua.", trap: "Gateway sai hoặc thiếu: vẫn ping được máy cùng subnet nhưng không ra được mạng khác.", interview: "Trên Linux xem default gateway bằng lệnh gì? (<code>ip route</code>)" },
        { front: "Vì sao server nên có IP tĩnh? Có những cách nào?", def: "Để client, DNS, firewall rule và log luôn trỏ đúng một địa chỉ. Cách 1: đặt tĩnh trên máy (netplan / IPv4 settings). Cách 2: <b>DHCP reservation / static mapping</b> theo MAC trên DHCP server. IP tĩnh nên nằm <b>ngoài dải pool</b>.", trap: "Đặt IP tĩnh nằm trong pool DHCP → có ngày DHCP cấp đúng IP đó cho máy khác → xung đột IP.", interview: "Static IP và DHCP reservation – ưu nhược điểm mỗi cách?" },
        { front: "Rule Anti-Lockout trên pfSense là gì?", def: "Rule tự động trên interface <b>LAN</b> luôn cho phép truy cập Web GUI (HTTP/HTTPS, và SSH nếu bật) tới pfSense, đặt trên mọi rule khác, để admin không <b>tự khóa mình</b> khi viết sai luật.", trap: "Chỉ có trên LAN – từ OPT1/OPT2 sẽ không vào được GUI nếu không có rule cho phép. Không bao giờ mở GUI ra WAN.", interview: "Bạn sẽ hạn chế truy cập trang quản trị firewall thế nào? (chỉ từ mạng quản trị, không mở ra WAN, đổi mật khẩu mặc định)" }
      ],
      whys: [
        "Hiểu đúng khái niệm trước khi làm: lab tạo nhiều <b>broadcast domain</b> bằng nhiều switch ảo, không phải 802.1Q. Phân biệt được điều này là điểm cộng khi phỏng vấn network admin.",
        "pfSense dựa trên <b>FreeBSD</b> nên chọn guest OS FreeBSD 64-bit để VMware giả lập phần cứng phù hợp. Router/firewall cần rất ít tài nguyên (1 vCPU, 1–2 GB).",
        "Mỗi card = một cổng của router nối vào một phân đoạn. Ghi MAC vì tên card trong pfSense (em0, em1…) không ghi VMnet nào – <b>MAC là cách duy nhất chắc chắn</b> để biết card nào cắm vào mạng nào.",
        "Cài hệ điều hành firewall lên đĩa ảo. Gỡ ISO sau khi cài để VM không khởi động lại vào trình cài đặt.",
        "Gán vai trò cho từng card (WAN/LAN/OPT). Trả lời <b>n</b> cho VLAN vì ta không dùng tag 802.1Q – mỗi phân đoạn đã có card riêng.",
        "Đặt IP gateway (.1) cho mỗi phân đoạn và bật <b>DHCP server</b> với pool .100–.199, chừa .2–.99 cho IP tĩnh. Interface nội bộ không có upstream gateway – chỉ WAN mới có “đường ra”.",
        "Cần một trình duyệt trong phân đoạn LAN để vào GUI. Đổi IP host adapter thành .250 vì VMware tự gán <b>.1 – trùng IP pfSense</b>. Không đặt gateway để Internet của host không đi vòng qua lab. GUI chỉ mở ở LAN = giảm attack surface.",
        "Đổi <b>default credentials</b> (admin/pfsense) là bước hardening bắt buộc – tài khoản mặc định là cửa bị dò đầu tiên (MITRE T1078.001). Đặt tên CLIENT/ATTACKER để rule và log dễ đọc.",
        "Xác nhận 2 dịch vụ cốt lõi: <b>DHCP</b> cấp IP cho từng phân đoạn và <b>Outbound NAT</b> dịch IP riêng 10.10.x.x ra IP WAN để ra Internet.",
        "Kiểm tra end-to-end theo lớp: nhận IP qua DHCP → gateway → IP Internet → DNS → HTTPS → đường đi (tracepath hop 1 = pfSense). Chứng minh mọi lưu lượng giờ đi <b>qua pfSense</b>.",
        "Server cần <b>IP cố định</b> để rule firewall, DNS và log luôn trỏ đúng. Tắt cloud-init quản lý mạng để cấu hình không bị ghi đè khi khởi động lại; <code>netplan try</code> là “lưới an toàn” tự quay lại nếu sai.",
        "Có một máy thử ở phân đoạn khác để quan sát <b>implicit deny</b>: nhận IP được nhưng không đi đâu được. Tạo lại machine-id để clone không trùng danh tính DHCP với máy gốc. Snapshot + backup config.xml = có đường lui."
      ]
    },

    /* ============================== N2 ============================== */
    "N2": {
      theory: [
        { title: "Least privilege & default deny cho mạng", body: "Mỗi vùng chỉ được đi tới đúng nơi, đúng port cần cho công việc; còn lại <b>chặn</b>. Cách làm chuẩn: viết <b>ma trận truy cập</b> (nguồn × đích × port) trước, rồi mới viết rule. Đây là <b>allowlist</b> – an toàn hơn denylist vì thứ bạn quên nghĩ tới sẽ bị chặn thay vì được cho qua." },
        { title: "pfSense xét rule: vào interface, trên xuống, khớp đầu tiên", body: "• Rule nằm ở tab của interface nơi gói <b>đi vào</b> pfSense (nơi kết nối bắt đầu). Muốn chặn ATTACKER → SERVER thì viết ở tab <b>ATTACKER</b>.<br>• Đọc <b>từ trên xuống</b>, gặp rule khớp đầu tiên là thực hiện và <b>dừng</b> (first match).<br>• Không khớp rule nào → <b>implicit deny</b>.<br>Quy tắc sắp xếp: pass hẹp ở trên → block rộng ở giữa → pass rộng (Internet) ở cuối." },
        { title: "Stateful firewall & state table", body: "Firewall <b>stateful</b> nhớ từng kết nối (IP, port, giao thức) trong <b>state table</b>. Khi chiều đi được rule cho phép, gói trả lời của cùng kết nối được cho qua <b>tự động</b> mà không xét lại rule ở interface phía bên kia. Vì vậy chỉ cần viết rule cho chiều <b>khởi tạo</b> kết nối.<br>Hệ quả: đổi rule <b>không cắt</b> kết nối đang có – phải Reset States hoặc chờ hết hạn." },
        { title: "Pass, Block, Reject", body: "<b>Pass</b>: cho qua. <b>Block</b>: âm thầm bỏ gói → phía gửi chờ đến <b>timeout</b>. <b>Reject</b>: bỏ gói <b>và báo lại</b> – với TCP gửi <b>RST</b> (thấy <i>connection refused</i> ngay), với UDP gửi <b>ICMP port unreachable</b>.<br>Trong nội bộ dùng Reject để người dùng/admin biết ngay bị chặn; hướng Internet thường dùng Block để không lộ thông tin và không tốn băng thông trả lời kẻ quét." },
        { title: "Alias", body: "Alias là <b>tên đặt cho nhóm IP / mạng / port</b> (vd <code>NET_SERVER</code>, <code>PORTS_CLIENT_SRV</code>). Rule dễ đọc hơn và sửa một chỗ áp dụng mọi rule. <code>PRIVATE_NETS</code> gồm 3 dải RFC 1918 – dùng để chặn đi ngang sang mọi mạng nội bộ (kể cả mạng VMware NAT 192.168.x)." },
        { title: "Port cần nhớ trong lab", body: "<b>22</b> SSH (TCP) · <b>53</b> DNS (UDP, và TCP) · <b>80</b> HTTP · <b>443</b> HTTPS · <b>3306</b> MySQL · <b>ICMP</b> không có port (ping = Echo Request type 8 / Echo Reply type 0)." },
        { title: "Firewall log – dữ liệu đầu tiên của SOC", body: "Mỗi dòng log trả lời: <b>ai</b> (source IP:port) – <b>tới đâu</b> (destination IP:port) – <b>giao thức</b> – <b>interface</b> – <b>rule nào</b> – <b>hành động</b> (pass/block). Bật log cho rule <b>block</b> để thấy hành vi bất thường; rule pass Internet thường không log vì quá nhiều, gây nhiễu và tốn dung lượng. <code>TCP:S</code> = gói SYN, tức cố mở kết nối mới." }
      ],
      pitfalls: [
        "<b>Đặt rule “Pass any” lên trên rule Block</b> → first match, rule chặn không bao giờ được xét. Pass hẹp → block rộng → pass rộng.",
        "<b>Viết rule nhầm tab</b>: muốn chặn ATTACKER → SERVER lại viết trên tab LAN. Rule áp dụng cho gói <b>đi vào</b> interface nơi kết nối bắt đầu.",
        "<b>Quên Apply Changes</b> sau Save → rule chưa có hiệu lực, test cho kết quả cũ.",
        "<b>Test ngay sau khi sửa rule mà kết nối cũ vẫn chạy</b> → do state cũ còn sống. Reset States (Diagnostics → States) hoặc mở kết nối mới.",
        "<b>Kết luận “port bị chặn” chỉ vì ping fail</b>: ICMP và TCP là rule khác nhau. Test đúng giao thức: <code>nc -vz IP port</code>, <code>curl</code>.",
        "<b>Quên tắt lại rule S1 / update Kali</b> sau khi dùng → Attacker có đường vào Server/Internet ngoài ý muốn."
      ],
      keycards: [
        { front: "pfSense xét firewall rule theo thứ tự nào? Không khớp rule nào thì sao?", def: "Rule ở tab của interface nơi gói <b>đi vào</b>, đọc <b>từ trên xuống</b>, khớp <b>rule đầu tiên</b> thì làm theo và dừng (first match). Không khớp rule nào → <b>implicit deny</b> (chặn).", example: "Bảo vệ đọc danh sách từ trên xuống, gặp dòng đầu tiên đúng với bạn là quyết định luôn, không đọc tiếp.", trap: "Đặt “Pass any” lên đầu thì mọi rule Block bên dưới vô tác dụng. (Floating rules có cơ chế riêng – không dùng trong lab này.)", interview: "Bạn sắp xếp rule thế nào cho đúng? (pass hẹp → block rộng → pass rộng)" },
        { front: "Firewall stateful là gì?", def: "Firewall nhớ từng kết nối trong <b>state table</b>; khi chiều khởi tạo được phép, gói trả lời của kết nối đó tự được cho qua mà <b>không xét lại rule</b>. Chỉ cần viết rule cho chiều mở kết nối.", example: "Bạn gọi điện ra ngoài được phép → người kia nói lại thì tổng đài không chặn, vì biết đang có cuộc gọi.", trap: "Vì vậy Client vào được web trên Server dù tab LAN có rule chặn Server → PRIVATE_NETS: gói trả lời đi theo state, không phải kết nối mới do Server mở.", interview: "Stateless ACL (ví dụ ACL Cisco thường) khác stateful firewall thế nào?" },
        { front: "Block và Reject khác nhau thế nào khi nhìn từ máy bị chặn?", def: "<b>Block</b>: gói bị bỏ im lặng → máy gửi chờ đến <b>timeout</b>.<br><b>Reject</b>: firewall trả lời từ chối → TCP nhận <b>RST</b> (<i>connection refused</i> ngay); UDP nhận <b>ICMP port unreachable</b>.", example: "Block = gọi điện không ai nhấc máy; Reject = có người nhấc lên nói “không tiếp” rồi cúp.", trap: "“Connection refused” cũng xảy ra khi đích không có dịch vụ nghe port đó (server tự gửi RST) – không phải lúc nào cũng do firewall.", interview: "Hướng Internet bạn dùng Block hay Reject? Vì sao? (Block: không lộ thông tin, không tốn tài nguyên trả lời kẻ quét)" },
        { front: "Muốn chặn ATTACKER (10.10.99.0/24) truy cập SERVER thì viết rule ở tab nào?", def: "Tab <b>ATTACKER</b> (OPT2) – interface nơi gói <b>đi vào</b> pfSense, vì kết nối bắt đầu từ ATTACKER. pfSense lọc trên chiều vào của interface.", trap: "Viết trên tab LAN (SERVER) không chặn được, vì gói từ ATTACKER đi vào ở OPT2 và đi ra ở LAN.", interview: "Ingress filtering và egress filtering là gì?" },
        { front: "Least privilege áp dụng cho firewall rule nghĩa là gì?", def: "Mỗi nguồn chỉ được tới đúng đích, đúng port cần cho công việc; mọi thứ khác bị chặn (<b>default deny</b>, allowlist). Ví dụ CLIENT → SERVER chỉ 22/80/443 + ping, ATTACKER bị cô lập.", example: "Nhân viên được thẻ ra vào đúng tầng mình làm việc, không có thẻ “đi mọi nơi”.", trap: "Rule “any-any” cho tiện lúc test rồi quên xóa là lỗi thật rất phổ biến khi audit.", interview: "Bạn sẽ thiết kế luật giữa vùng User và vùng Server ra sao?" },
        { front: "Đọc dòng log: <code>BLOCK | ATTACKER | Co lap Attacker | 10.10.99.101:51514 | 10.10.10.10:22 | TCP:S</code>", def: "Máy <b>10.10.99.101</b> (port nguồn ngẫu nhiên 51514) cố mở kết nối <b>SSH</b> (TCP 22) tới <b>10.10.10.10</b>; gói vào ở interface ATTACKER và bị chặn bởi rule “Co lap Attacker”. <code>TCP:S</code> = cờ <b>SYN</b> – gói đầu tiên mở kết nối.", trap: "Port nguồn cao (49152+…) là port tạm của client, không phải dịch vụ – dịch vụ là port <b>đích</b>.", interview: "Thấy một IP gửi SYN tới hàng trăm port khác nhau trong vài giây – đó là gì? (port scan)" },
        { front: "Alias trên pfSense dùng để làm gì?", def: "Đặt <b>tên cho nhóm IP, mạng hoặc port</b> (vd <code>NET_SERVER</code>, <code>PORTS_CLIENT_SRV</code> = 22,80,443). Rule dễ đọc, ít sai, sửa alias một lần là mọi rule dùng nó thay đổi theo.", trap: "Sửa alias ảnh hưởng tới <b>tất cả</b> rule đang dùng nó – kiểm tra trước khi đổi.", interview: "Làm sao để bộ rule firewall vài trăm dòng vẫn dễ quản lý?" },
        { front: "Vì sao rule Block nên bật log, còn rule cho phép ra Internet thường không?", def: "Log của rule chặn cho thấy hành vi <b>bất thường</b> (quét, đi ngang, cố vào vùng cấm) – có giá trị điều tra. Rule pass Internet khớp hàng nghìn kết nối bình thường → log quá nhiều, nhiễu, tốn dung lượng/chi phí SIEM.", trap: "Không log gì cả thì khi có sự cố sẽ không có bằng chứng – cân bằng giữa nhiễu và khả năng điều tra.", interview: "Firewall log cho SOC biết những thông tin gì?" }
      ],
      whys: [
        "Thiết kế trước, cấu hình sau: <b>ma trận truy cập</b> biến yêu cầu nghiệp vụ thành luật rõ ràng, và là tài liệu để audit/đối chiếu. Nắm 4 quy tắc (vào interface, first match, implicit deny, stateful) thì đọc được mọi bộ rule.",
        "Cần một dịch vụ thật (nginx port 80, SSH 22) để kiểm chứng rule cho phép/chặn đúng. Snapshot trước khi sửa firewall = luôn có đường lui (change management).",
        "<b>Alias</b> giúp rule đọc như câu nói (“Client tới Server port 22/80/443”) và sửa một chỗ áp dụng mọi nơi. <code>PRIVATE_NETS</code> = 3 dải RFC 1918 để chặn đi ngang sang mọi mạng nội bộ.",
        "Áp dụng <b>least privilege</b> cho CLIENT và minh họa <b>first match</b>: rule cho phép hẹp ở trên, block nội bộ ở giữa, nên rule “any” cuối cùng chỉ còn tác dụng ra Internet.",
        "Server không cần tự mở kết nối sang mạng khác – chặn để nếu Server bị chiếm thì khó <b>lateral movement</b>. Disable thay vì xóa để có thể bật lại. Client vẫn vào được Server nhờ <b>stateful</b>.",
        "Attacker được <b>cô lập</b> mặc định; rule đặc biệt tạo sẵn nhưng Disabled – chỉ bật khi cần cho đúng bài lab. Đây là quản lý rule tạm thời có kiểm soát, và đảm bảo Kali không đụng tới mạng thật.",
        "Rule chỉ có hiệu lực sau <b>Apply</b>. Thứ tự quyết định kết quả (first match). Kết nối cũ vẫn sống theo <b>state</b> nên phải reset để test sạch.",
        "Kiểm chứng từng dòng của ma trận: cái cần mở thì mở, cái cần chặn thì chặn. Dùng đúng công cụ cho đúng giao thức (ping = ICMP, <code>nc</code>/<code>curl</code> = TCP). Timeout = dấu hiệu của <b>Block</b>.",
        "Kiểm tra vùng bị cô lập từ chính góc nhìn của kẻ tấn công – chỉ DNS được phép. Bật/tắt thử rule S1 để hiểu rule Disabled hoạt động thế nào.",
        "Đây là kỹ năng SOC cốt lõi: đọc một dòng log và trả lời <b>ai – tới đâu – port nào – rule nào – kết quả</b>. Lọc theo IP nguồn là thao tác điều tra cơ bản.",
        "Backup config = khôi phục được khi lỗi; ảnh chụp rule + bảng kết quả test = tài liệu cho portfolio. Không đẩy config.xml công khai vì chứa hash mật khẩu (bảo vệ thông tin nhạy cảm)."
      ]
    },

    /* ============================== S8 ============================== */
    "S8": {
      theory: [
        { title: "DNS và bản ghi A", body: "<b>DNS</b> đổi tên miền thành IP – như danh bạ điện thoại của Internet. Truy vấn thường đi bằng <b>UDP 53</b> (nhanh, 1 hỏi – 1 đáp). Dùng <b>TCP 53</b> khi phản hồi quá lớn (bị đánh dấu truncated) và khi <b>zone transfer</b> (AXFR) giữa các DNS server.<br>Bản ghi <b>A</b> = tên → IPv4; <b>AAAA</b> = tên → IPv6. Trong tcpdump, <code>A?</code> là câu hỏi “IPv4 của tên này là gì?”." },
        { title: "UDP không có “từ chối kết nối”", body: "TCP có bắt tay 3 bước và cờ <b>RST</b> để báo từ chối. <b>UDP không có kết nối</b> nên không có RST; cách duy nhất để báo “không có ai nghe ở port này” là gói <b>ICMP Destination Unreachable – Port Unreachable</b> (type 3, code 3) do máy đích hoặc firewall gửi về. Không có phản hồi nào thì client chỉ biết chờ rồi <b>timeout</b>." },
        { title: "ICMP – giao thức báo lỗi của tầng mạng", body: "ICMP (lớp 3, đi kèm IP) không mang dữ liệu người dùng mà mang <b>thông báo</b>: Echo Request/Reply (ping, type 8/0), Destination Unreachable (type 3: code 0 net, 1 host, 3 <b>port</b>, 13 bị chặn bởi quản trị), Time Exceeded (type 11, dùng trong traceroute). Thông báo “udp port 53 unreachable” trong Khóa 3 chính là ICMP type 3 code 3." },
        { title: "tcpdump & bộ lọc BPF", body: "<b>tcpdump</b> bắt gói trên một interface (cần sudo). Tùy chọn hay dùng: <code>-i ens33</code> chọn card, <code>-nn</code> không đổi IP/port thành tên, <code>-w file.pcap</code> ghi ra file, <code>-r file.pcap</code> đọc lại, <code>-c 10</code> dừng sau 10 gói, <code>-v</code> chi tiết hơn.<br>Bộ lọc <b>BPF</b> đặt cuối lệnh, trong nháy đơn: <code>'port 53 or icmp'</code>, <code>'host 10.10.10.1 and udp'</code>, <code>'not port 22'</code>. (Khóa 6 – packet capture.)" },
        { title: "Đọc một dòng tcpdump DNS", body: "<code>10:15:02.101 IP 10.10.10.10.41234 &gt; 10.10.10.1.53: 51234+ [1au] A? example.com. (52)</code><br>• thời gian · <b>IP nguồn.port nguồn</b> &gt; <b>IP đích.port đích</b><br>• <code>51234</code> = Transaction ID (câu trả lời có cùng ID) · <code>+</code> = recursion desired · <code>[1au]</code> = 1 bản ghi additional (EDNS) · <code>A?</code> = hỏi bản ghi A · <code>(52)</code> = độ dài.<br>Dòng trả lời <code>1/0/1 A 93.184.215.14</code> = 1 answer / 0 authority / 1 additional." },
        { title: "pcap là bằng chứng", body: "File <b>.pcap</b> lưu nguyên gói tin kèm thời gian – có thể đọc lại bằng tcpdump hoặc Wireshark, chia sẻ cho đồng đội, đính vào ticket. Analyst lưu bằng chứng thay vì chỉ nhìn màn hình, và <b>đối chiếu (correlate)</b> nhiều nguồn: pcap trên máy + firewall log, khớp nhau về thời gian." },
        { title: "Viết incident report (Khóa 6)", body: "Báo cáo tốt trả lời: <b>chuyện gì</b> (tóm tắt), <b>bằng chứng gì</b> (log, pcap), <b>khi nào</b> (timeline), <b>vì sao</b> (phân tích giao thức, nguyên nhân gốc), <b>nghiêm trọng thế nào</b>, <b>thật hay false positive</b>, <b>đề xuất</b> khắc phục và phòng ngừa. Dùng số liệu thật từ bằng chứng, không đoán." }
      ],
      pitfalls: [
        "<b>Đặt rule S8 TEST ở cuối danh sách</b> → rule “DNS toi pfSense” ở trên khớp trước (first match), DNS vẫn chạy, không thấy lỗi. Phải thêm ở <b>đầu</b>.",
        "<b>Dùng <code>dig example.com</code> không có <code>@10.10.10.1</code></b> → câu trả lời có thể lấy từ bộ đệm systemd-resolved (127.0.0.53), không có gói nào ra mạng, tcpdump trống.",
        "<b>Bắt sai interface</b> (vd <code>-i lo</code> hoặc <code>any</code> rồi lẫn gói) → không thấy gì hoặc thấy gói trùng. Kiểm tra tên card bằng <code>ip -br a</code>.",
        "<b>Quên <code>-nn</code></b> → tcpdump in <code>.domain</code> thay vì <code>.53</code> và có thể tự tra DNS ngược, sinh thêm gói DNS làm rối log.",
        "<b>Bắt qua SSH mà không lọc</b> → tcpdump bắt cả gói SSH của chính phiên đang xem, màn hình chạy liên tục. Dùng bộ lọc <code>'port 53 or icmp'</code> (hoặc thêm <code>and not port 22</code>).",
        "<b>Quên xóa rule S8 TEST</b> sau bài → Ubuntu mất DNS, apt và các lab sau lỗi khó hiểu. Luôn khôi phục và kiểm tra <code>dig</code> có ANSWER SECTION."
      ],
      keycards: [
        { front: "DNS dùng port và giao thức nào? Khi nào dùng TCP?", def: "<b>Port 53</b>. Truy vấn thường dùng <b>UDP</b> (nhanh, không cần bắt tay). Dùng <b>TCP 53</b> khi phản hồi quá lớn (bị truncated, client hỏi lại bằng TCP) và khi <b>zone transfer</b> (AXFR) giữa các DNS server.", example: "UDP = hỏi nhanh qua điện thoại; TCP = gửi cả cuốn danh bạ bằng chuyển phát có ký nhận.", trap: "Chỉ mở UDP 53 trên firewall có thể làm lỗi các truy vấn lớn (DNSSEC) – thường mở cả TCP/UDP 53 tới DNS server nội bộ.", interview: "Vì sao zone transfer từ ngoài Internet là rủi ro bảo mật?" },
        { front: "Trong tcpdump, <code>ICMP 10.10.10.1 udp port 53 unreachable</code> nghĩa là gì?", def: "Máy/firewall 10.10.10.1 trả về <b>ICMP Destination Unreachable – Port Unreachable</b> (type 3 code 3): gói UDP tới port 53 <b>không được dịch vụ nào nhận</b> (dịch vụ DNS không chạy, hoặc firewall Reject). Kết quả: không phân giải được tên miền.", example: "Gửi thư tới đúng tòa nhà nhưng bưu tá báo “phòng 53 không có người” và trả thư lại.", trap: "Có ICMP unreachable nghĩa là <b>đường tới host vẫn thông</b> (có thiết bị trả lời) – vấn đề ở dịch vụ/port, không phải mất mạng.", interview: "ICMP type 3 code 3 khác code 13 thế nào? (port unreachable vs communication administratively prohibited)" },
        { front: "Giải nghĩa: <code>51234+ [1au] A? example.com. (52)</code>", def: "<b>51234</b> = Transaction ID (câu trả lời mang cùng ID); <b>+</b> = recursion desired (nhờ server hỏi hộ tới cùng); <b>[1au]</b> = 1 bản ghi trong phần additional (thường là EDNS OPT); <b>A?</b> = hỏi bản ghi A (IPv4); <b>(52)</b> = độ dài phần DNS.", trap: "<code>A?</code> có dấu hỏi là <b>câu hỏi</b>; dòng trả lời có <code>A 93.x.x.x</code> không có dấu hỏi.", interview: "Làm sao ghép một truy vấn DNS với câu trả lời của nó trong pcap? (cùng Transaction ID, đảo IP/port)" },
        { front: "Firewall Reject UDP và Block UDP – tcpdump trên client thấy gì khác nhau?", def: "<b>Reject</b>: thấy truy vấn <code>A?</code> và ngay sau đó dòng <b>ICMP … udp port 53 unreachable</b>; dig báo lỗi gần như tức thì (<i>connection refused</i>).<br><b>Block</b>: chỉ thấy các dòng <code>A?</code> lặp lại (retry), <b>không có phản hồi</b>; dig chờ rồi báo <b>timed out</b>.", example: "Reject = nhân viên trả lời “không phục vụ”; Block = gọi mãi không ai nghe.", trap: "Chỉ timeout không có nghĩa chắc chắn là firewall Block – cũng có thể server chết, mất gói, sai route.", interview: "Chỉ thấy truy vấn lặp lại mà không có phản hồi – bạn nghĩ tới những nguyên nhân nào?" },
        { front: "Các tùy chọn tcpdump: <code>-i</code>, <code>-nn</code>, <code>-w</code>, <code>-r</code>, <code>-c</code>?", def: "<code>-i ens33</code> chọn interface · <code>-nn</code> không đổi IP thành tên và port thành tên dịch vụ · <code>-w file.pcap</code> ghi gói thô ra file · <code>-r file.pcap</code> đọc file · <code>-c N</code> dừng sau N gói. Bộ lọc BPF đặt cuối, vd <code>'port 53 or icmp'</code>.", example: "<code>sudo tcpdump -i ens33 -nn -w dns.pcap 'udp port 53'</code>", trap: "Khi <code>-w</code>, màn hình không in gói (đã ghi vào file) – không phải tcpdump bị treo.", interview: "Vì sao log trong khóa học hiện <code>.domain</code> còn bạn thấy <code>.53</code>? (khóa học không dùng <code>-nn</code>)" },
        { front: "UDP không có kết nối – vậy làm sao bên gửi biết port đích đóng?", def: "Máy đích (hoặc firewall Reject) gửi lại <b>ICMP Port Unreachable</b> (type 3 code 3). Nếu không có ICMP nào quay về, bên gửi không biết gì và chỉ <b>timeout</b>. TCP thì khác: port đóng trả <b>RST</b>.", trap: "Nhiều firewall chặn cả ICMP đi ra → quét UDP rất chậm và khó kết luận (nmap báo <i>open|filtered</i>).", interview: "Port scan UDP khó hơn TCP ở điểm nào?" },
        { front: "Vì sao analyst lưu file pcap và đối chiếu với firewall log?", def: "pcap là <b>bằng chứng gốc</b> đọc lại được, chia sẻ được (Wireshark). Đối chiếu (<b>correlate</b>) hai nguồn độc lập – pcap trên máy và log firewall – khớp thời gian, IP, port giúp kết luận chắc chắn nguyên nhân thay vì phỏng đoán.", trap: "Giờ trên các máy phải đồng bộ (NTP) và cùng múi giờ, nếu không timeline lệch, khó khớp.", interview: "Một incident report tốt cần những phần nào?" }
      ],
      whys: [
        "Đặt mục tiêu rõ: tái hiện đúng hiện tượng trong Khóa 3 để hiểu nó <b>từ bên trong</b>. Khi tự gây ra lỗi, bạn biết chắc nguyên nhân và học được cách nhận ra nó trong log thật.",
        "Một phiên bắt gói, một phiên tạo lưu lượng – để thấy nguyên nhân và kết quả cùng lúc. Phải biết tên interface thì tcpdump mới bắt đúng chỗ.",
        "<b>Baseline</b> = biết “bình thường” trông thế nào (1 hỏi – 1 đáp, cùng ID) thì mới nhận ra “bất thường”. Hỏi thẳng <code>@10.10.10.1</code> để gói chắc chắn đi ra mạng, không bị bộ đệm nội bộ trả lời.",
        "Tạo lỗi có kiểm soát bằng <b>Reject</b> UDP 53. Đặt ở đầu danh sách vì <b>first match</b> – nằm dưới rule cho phép DNS thì không bao giờ được xét. Bật Log để có nguồn bằng chứng thứ hai.",
        "Thấy tận mắt cặp dòng <code>A?</code> + <b>ICMP udp port 53 unreachable</b> – đúng mẫu log trong Khóa 3. Hiểu vì sao với UDP, “connection refused” đến từ ICMP chứ không phải RST.",
        "Ghi bằng chứng ra file <b>.pcap</b> để đọc lại, đếm, chia sẻ và đính kèm báo cáo. <code>+tries=1</code> để mỗi lần dig chỉ gửi một truy vấn → đếm số lỗi chính xác.",
        "So sánh hai hành vi firewall: <b>Reject</b> có phản hồi ICMP, <b>Block</b> chỉ có im lặng và timeout. Nhận ra triệu chứng nào dẫn tới hướng điều tra nào là kỹ năng phân tích quan trọng.",
        "<b>Correlation</b>: hai nguồn độc lập (pcap trên máy + log firewall) khớp thời gian, IP, port → kết luận chắc chắn. Đây là tư duy cốt lõi của SOC.",
        "Ánh xạ lab với bài khóa học giúp chuyển kiến thức lý thuyết thành kinh nghiệm thực tế – và có câu chuyện cụ thể để kể khi phỏng vấn.",
        "Kỹ năng viết <b>incident report</b> (Khóa 6): tóm tắt, bằng chứng, timeline, phân tích, nguyên nhân gốc, mức độ, thật/false positive, đề xuất. Dùng số liệu thật từ pcap, không đoán.",
        "Khôi phục về trạng thái sạch và <b>xác minh</b> dịch vụ đã hoạt động lại (bước “recovery” trong vòng đời xử lý sự cố). Xóa cache DNS để chắc kết quả không đến từ bộ đệm cũ."
      ]
    },

    /* ============================== PT-1 ============================== */
    "PT-1": {
      theory: [
        { title: "Switch (lớp 2) và Router (lớp 3)", body: "<b>Switch</b> chuyển frame trong <b>cùng một mạng</b> dựa trên <b>địa chỉ MAC</b>, học MAC vào <b>MAC address table</b>. <b>Router</b> nối <b>các mạng khác nhau</b> và chuyển gói dựa trên <b>địa chỉ IP</b> theo <b>routing table</b>. Mỗi cổng router là một subnet riêng (và là gateway của subnet đó)." },
        { title: "Các mode của Cisco IOS", body: "<code>Router&gt;</code> <b>User EXEC</b>: xem cơ bản.<br><code>Router#</code> <b>Privileged EXEC</b> (gõ <code>enable</code>): mọi lệnh show, copy, reload.<br><code>Router(config)#</code> <b>Global configuration</b> (<code>configure terminal</code>): cấu hình chung cho thiết bị.<br><code>Router(config-if)#</code> <b>Interface configuration</b> (<code>interface g0/0</code>): cấu hình riêng một cổng.<br><code>exit</code> lùi 1 mức; <code>end</code> hoặc Ctrl+Z về thẳng <code>#</code>." },
        { title: "running-config và startup-config", body: "<b>running-config</b> = cấu hình đang chạy, nằm trong <b>RAM</b>; mọi lệnh bạn gõ có hiệu lực ngay ở đây nhưng <b>mất khi khởi động lại</b>.<br><b>startup-config</b> = cấu hình nạp khi khởi động, nằm trong <b>NVRAM</b>.<br><code>copy running-config startup-config</code> (viết tắt <code>copy run start</code>, hoặc <code>write memory</code>) để lưu lại.<br>Ví dụ đời thường: running = bài đang soạn trên màn hình; startup = file đã bấm Save." },
        { title: "Cổng router mặc định tắt, cổng switch mặc định bật", body: "Interface router Cisco mặc định ở trạng thái <b>administratively down</b> – phải <code>no shutdown</code>. Cổng switch 2960 mặc định bật, cắm là chạy. Đọc <code>show ip interface brief</code>: <b>administratively down</b> = quên no shutdown; <b>down/down</b> = lỗi dây hoặc đầu kia tắt; <b>up/down</b> = lỗi lớp 2 (encapsulation, keepalive…); <b>up/up</b> = tốt." },
        { title: "Cáp straight-through và cross-over", body: "Thiết bị chia 2 nhóm theo cách dùng chân dây: <b>nhóm đầu cuối</b> (PC, router, server) và <b>nhóm switch/hub</b>. <b>Khác nhóm</b> → <b>straight-through</b> (PC–switch, switch–router). <b>Cùng nhóm</b> → <b>cross-over</b> (PC–router, PC–PC, switch–switch, router–router).<br>Thiết bị hiện đại thường có <b>Auto-MDIX</b> tự đảo chân, nhưng câu hỏi này vẫn hay xuất hiện khi phỏng vấn." },
        { title: "ARP và vì sao gói ping đầu tiên hay mất", body: "Để gửi frame, máy cần <b>MAC</b> của đích (cùng subnet) hoặc của <b>gateway</b> (khác subnet). <b>ARP</b> hỏi broadcast “ai có IP X?” và nhận MAC trả lời. Lần đầu chưa có trong ARP cache nên gói đầu tiên có thể timeout trong lúc chờ ARP – bình thường." },
        { title: "Bảng định tuyến: route C và L", body: "Khi cổng router có IP và <b>up/up</b>, router tự thêm route <b>C (connected)</b> cho cả subnet (vd 192.168.10.0/24) và route <b>L (local)</b> /32 cho chính IP của cổng (vd 192.168.10.1/32). Vì 2 subnet đều nối trực tiếp, router chuyển gói giữa chúng mà <b>không cần static route</b>." }
      ],
      pitfalls: [
        "<b>Quên <code>no shutdown</code></b> trên cổng router → <code>show ip int br</code> hiện <i>administratively down</i>, đèn đỏ, ping fail.",
        "<b>Quên <code>copy run start</code></b> → tắt/reload router (hoặc đóng Packet Tracer không lưu) là mất cấu hình. Lưu cả router <b>và</b> switch, rồi lưu file .pkt.",
        "<b>Gõ lệnh sai mode</b> → “% Invalid input detected”. Ví dụ <code>ip address</code> phải ở <code>(config-if)#</code>; <code>show</code> ở <code>#</code> (trong config mode dùng <code>do show …</code>).",
        "<b>Gateway của PC đặt sai</b> (khác subnet, hoặc trỏ nhầm IP cổng bên kia) → ping được trong subnet nhưng không sang subnet khác.",
        "<b>Chọn sai loại cáp</b> PC1 – router (straight-through) → link không lên trong Packet Tracer. PC–router cần cross-over.",
        "<b>Gõ sai lệnh mà chưa có <code>no ip domain-lookup</code></b> → router coi từ gõ sai là hostname và đi tra DNS, treo vài chục giây (thoát bằng Ctrl+Shift+6)."
      ],
      keycards: [
        { front: "Kể tên 4 mode IOS cơ bản, dấu nhắc và lệnh để vào mỗi mode.", def: "<code>Router&gt;</code> User EXEC (mặc định khi vào).<br><code>Router#</code> Privileged EXEC – lệnh <code>enable</code>.<br><code>Router(config)#</code> Global config – <code>configure terminal</code>.<br><code>Router(config-if)#</code> Interface config – <code>interface g0/0</code>.<br><code>exit</code> lùi 1 mức, <code>end</code>/Ctrl+Z về <code>#</code>.", example: "Như vào tòa nhà: sảnh (&gt;) → quẹt thẻ lên văn phòng (#) → vào phòng kỹ thuật (config) → mở tủ một thiết bị (config-if).", trap: "Muốn chạy <code>show</code> khi đang ở config mode phải thêm <code>do</code>: <code>do show ip int br</code>.", interview: "Lỗi “% Invalid input detected at ^ marker” thường do đâu?" },
        { front: "running-config khác startup-config thế nào? Lệnh lưu cấu hình?", def: "<b>running-config</b> ở <b>RAM</b>, có hiệu lực ngay, mất khi reload/mất điện. <b>startup-config</b> ở <b>NVRAM</b>, nạp lúc khởi động.<br>Lưu: <code>copy running-config startup-config</code> (= <code>copy run start</code> = <code>write memory</code>).", example: "Running = văn bản đang gõ; startup = file đã Save. Mất điện trước khi Save là mất bài.", trap: "Cấu hình sai mà chưa lưu → <code>reload</code> sẽ quay về startup-config cũ – cũng là một cách rollback.", interview: "Bạn sửa cấu hình switch xong, sáng hôm sau mất hết – nguyên nhân có thể là gì?" },
        { front: "Vì sao cổng router không lên dù đã cắm dây và đặt IP?", def: "Interface router Cisco mặc định <b>shutdown</b>. Phải vào <code>interface g0/0</code> và gõ <code>no shutdown</code>. Kiểm tra <code>show ip interface brief</code>: <i>administratively down</i> = quên no shutdown.", trap: "Cổng <b>switch</b> 2960 mặc định đã bật – chỉ router mới cần no shutdown ở bài này.", interview: "Đọc trạng thái “up/down” trong <code>show ip int brief</code> nghĩa là gì? (lớp 1 lên, lớp 2 có vấn đề)" },
        { front: "Khi nào dùng cáp straight-through, khi nào dùng cross-over?", def: "<b>Khác nhóm</b> thiết bị → straight-through: PC–switch, switch–router.<br><b>Cùng nhóm</b> → cross-over: PC–router, PC–PC, switch–switch, router–router.<br>(Nhóm 1: PC, router, server. Nhóm 2: switch, hub.)", trap: "PC và router nhìn khác nhau nhưng cùng nhóm “đầu cuối” → cross-over. Thiết bị có Auto-MDIX thì loại nào cũng chạy.", interview: "Auto-MDIX là gì?" },
        { front: "<code>enable secret</code> khác <code>enable password</code> thế nào?", def: "<code>enable secret</code> lưu mật khẩu dạng <b>hash</b> (type 5 MD5 trên nhiều IOS, bản mới hỗ trợ type 8/9). <code>enable password</code> là kiểu cũ, lưu <b>rõ chữ</b> trong running-config (hoặc type 7 nếu bật <code>service password-encryption</code> – rất yếu, giải ngược được). Nếu có cả hai, <b>secret được ưu tiên</b>.", trap: "Type 7 không phải mã hóa thật – có tool giải ngược trong vài giây.", interview: "Liệt kê vài bước hardening cơ bản cho thiết bị Cisco." },
        { front: "PC0 (192.168.10.10) muốn ping PC1 (192.168.20.10) ở subnet khác – gói đi thế nào?", def: "PC0 thấy đích <b>khác subnet</b> → gửi tới <b>default gateway</b> 192.168.10.1 (ARP để lấy MAC của gateway). Router tra bảng định tuyến, thấy 192.168.20.0/24 là <b>connected</b> trên Gi0/1 → ARP tìm MAC của PC1 → chuyển gói.", example: "Gửi thư liên tỉnh: đưa cho bưu cục (gateway), bưu cục biết tuyến nào đi tỉnh kia.", trap: "Ping gateway 192.168.10.1 không cần gateway (cùng subnet); ping PC1 thì bắt buộc PC0 phải có gateway đúng.", interview: "Ping từ trong ra ngoài (gateway trước) giúp khoanh vùng lỗi như thế nào?" },
        { front: "Đọc <code>show ip interface brief</code>: các trạng thái Status/Protocol nghĩa là gì?", def: "<b>up / up</b>: hoạt động tốt.<br><b>administratively down / down</b>: bị <code>shutdown</code> (quên no shutdown).<br><b>down / down</b>: lỗi lớp 1 – dây, đầu kia tắt.<br><b>up / down</b>: lớp 1 ổn nhưng lớp 2 có vấn đề (encapsulation, keepalive…).", trap: "Đọc Status là lớp 1 (vật lý), Protocol là lớp 2 (data link).", interview: "Một cổng ở down/down – bạn kiểm tra những gì?" },
        { front: "Switch và router khác nhau thế nào (lớp OSI, địa chỉ dùng để chuyển tiếp)?", def: "<b>Switch</b> – lớp 2, chuyển frame dựa trên <b>MAC</b>, học MAC vào MAC address table, hoạt động trong một mạng/VLAN.<br><b>Router</b> – lớp 3, chuyển gói giữa <b>các mạng khác nhau</b> dựa trên <b>IP</b> và routing table; mỗi cổng là một broadcast domain.", example: "Switch = người đưa thư trong một chung cư (biết số phòng); router = bưu điện chuyển thư giữa các khu phố.", trap: "Switch lớp 3 (multilayer) có thể định tuyến – nhưng switch 2960 trong bài là lớp 2.", interview: "Lệnh xem bảng MAC trên switch Cisco? (<code>show mac address-table</code>)" }
      ],
      whys: [
        "Packet Tracer là công cụ mô phỏng chính thức của Cisco, miễn phí – cho phép luyện cú pháp IOS và các khái niệm CCNA (VLAN, trunk, routing) mà không cần thiết bị thật. Tải từ nguồn chính thức.",
        "Chọn đúng loại cáp là kiến thức lớp 1: <b>khác nhóm</b> thiết bị dùng straight-through, <b>cùng nhóm</b> (PC–router) dùng cross-over. Đèn đỏ ở router nhắc rằng cổng router mặc định tắt.",
        "Mỗi PC cần IP, mask (biết ai cùng mạng) và <b>default gateway</b> (cửa ra mạng khác). Gateway phải là IP cổng router <b>cùng subnet</b>.",
        "Biết mình đang ở <b>mode</b> nào là nền tảng của mọi thao tác IOS – phần lớn lỗi “Invalid input” do gõ đúng lệnh nhưng sai mode.",
        "Hardening tối thiểu: đặt tên để nhận diện thiết bị (trong log, trong dấu nhắc), <code>enable secret</code> dạng hash để bảo vệ quyền quản trị, banner cảnh báo pháp lý, <code>no ip domain-lookup</code> để gõ sai không bị treo.",
        "Mỗi cổng router là <b>gateway của một subnet</b>. Router chỉ tạo route connected khi cổng có IP và ở trạng thái up – <code>no shutdown</code> là bước bắt buộc.",
        "Switch lớp 2 chạy được ngay, nhưng admin vẫn đặt tên + mật khẩu (không để thiết bị mặc định). <code>show mac address-table</code> cho thấy switch học MAC từ cổng nào.",
        "Kiểm chứng bằng lệnh <code>show</code> thay vì đoán: trạng thái cổng (lớp 1/2), cấu hình đang chạy, bảng định tuyến (2 route <b>C</b> connected, kèm route <b>L</b> local).",
        "Kiểm tra end-to-end theo hướng <b>từ trong ra ngoài</b> (gateway → cổng xa → PC1) để khoanh vùng lỗi. Simulation mode cho thấy ARP rồi mới tới ICMP – hiểu vì sao gói đầu có thể mất.",
        "Cấu hình chỉ an toàn khi đã nằm trong <b>NVRAM</b> (startup-config). Quên lưu là lỗi thực tế rất phổ biến: thiết bị khởi động lại là mất hết. File .pkt là sản phẩm cho portfolio."
      ]
    }
  };

  (DATA.labs || []).forEach(function (l) {
    var x = EXTRA[l.id]; if (!x) return;
    if (x.theory && !l.theory) l.theory = x.theory;
    if (x.pitfalls && !l.pitfalls) l.pitfalls = x.pitfalls;
    if (x.keycards && !l.keycards) l.keycards = x.keycards;
    (x.whys || []).forEach(function (w, i) { if (l.steps[i] && w && !l.steps[i].why) l.steps[i].why = w; });
  });
})();
